     * A dimension without an entitlement is chargeable in full.
     */
    static chargeableUsage({ dimension, total }: { dimension: ReadDimensionResponseData; total: number }): number {
        const usageEntitlement = dimension?.usageEntitlement;
        const usageTotal = Number.isFinite(total) ? total : 0;
